def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                colors.setdefault(grid[r][c], []).append((r, c))

    objects = []
    for color, cells in colors.items():
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        tile = [[color if (r, c) in set(cells) else 0
                 for c in range(c0, c1 + 1)]
                for r in range(r0, r1 + 1)]
        objects.append((r0, c0, tile))

    centers_y = [r + (len(tile) - 1) / 2 for r, c, tile in objects]
    centers_x = [c + (len(tile[0]) - 1) / 2 for r, c, tile in objects]
    horizontal = max(centers_x) - min(centers_x) >= max(centers_y) - min(centers_y)

    if horizontal:
        objects.sort(key=lambda obj: obj[1])
        out = [[0] * sum(len(tile[0]) for _, _, tile in objects)
               for _ in range(max(len(tile) for _, _, tile in objects))]
        offset = 0
        for _, _, tile in objects:
            for r, row in enumerate(tile):
                out[r][offset:offset + len(row)] = row
            offset += len(tile[0])
    else:
        objects.sort(key=lambda obj: obj[0])
        out = [[0] * max(len(tile[0]) for _, _, tile in objects)
               for _ in range(sum(len(tile) for _, _, tile in objects))]
        offset = 0
        for _, _, tile in objects:
            for r, row in enumerate(tile):
                out[offset + r][:len(row)] = row
            offset += len(tile)

    return out
